```ts
// a.ts
import { fromB } from './b';
export const fromA = () => fromB() + 1;

// b.ts
import { fromA } from './a';
export const fromB = () => fromA() + 1;

// consumer.ts
import { fromA } from './a';
console.log(fromA());
// Broken output (depending on bundler): TypeError: fromB is not a function
// because at the moment a.ts is evaluated, b.ts hasn't finished initialising and fromB is still undefined.
